const profile = $input.first().json.profile;
const searchQuery = $input.first().json.searchQuery;

const keywords = encodeURIComponent(searchQuery);
const location = encodeURIComponent('United States');

// API URL (returns more jobs than main page)
const baseUrl = `https://www.linkedin.com/jobs-guest/jobs/api/seeMoreJobPostings/search?keywords=${keywords}&location=${location}&f_TPR=r86400`;

// Return 3 items - each will trigger HTTP request separately
return [
  { json: { url: `${baseUrl}&start=0`, batch: 1, profile, searchQuery } },
  { json: { url: `${baseUrl}&start=10`, batch: 2, profile, searchQuery } },
  { json: { url: `${baseUrl}&start=20`, batch: 3, profile, searchQuery } }
];

// Get the text from Gemini's response structure
const geminiText = $input.first().json.content.parts[0].text;

// Remove markdown code blocks
let jsonStr = geminiText
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

// Parse the JSON
let profileData;
try {
  profileData = JSON.parse(jsonStr);
} catch (e) {
  return [{
    json: {
      error: 'Failed to parse JSON',
      rawText: jsonStr
    }
  }];
}

// Build search query from actual data
const currentRole = profileData.current_role || 'Software Engineer';
const domain = profileData.domains?.[0] || '';
const searchQuery = `${currentRole} ${domain}`.trim();

return [{
  json: {
    profile: profileData,
    searchQuery: searchQuery
  }
}];

// Get ALL items (3 HTTP responses)
const allItems = $input.all();

// Get profile from first item
let profile = {};
let searchQuery = '';
try {
  profile = allItems[0].json.profile || $('LinkedIn Search URL').first().json.profile || {};
  searchQuery = allItems[0].json.searchQuery || $('LinkedIn Search URL').first().json.searchQuery || '';
} catch(e) {
  profile = { name: 'Unknown' };
}

const allJobs = [];
const seenUrls = new Set();

// Process each batch of HTML
for (const item of allItems) {
  const html = item.json.data || '';

  // Split by job cards
  const jobCards = html.split('<li>').slice(1);

  for (const card of jobCards) {
    // Extract job title
    const titleMatch = card.match(/base-search-card__title[^>]*>\s*([\s\S]*?)\s*<\/h3>/i);
    let title = titleMatch ? titleMatch[1].trim() : '';

    // Extract company name
    const companyMatch = card.match(/hidden-nested-link[^>]*>\s*([\s\S]*?)\s*<\/a>/i);
    let company = companyMatch ? companyMatch[1].trim() : '';

    // Extract location
    const locationMatch = card.match(/job-search-card__location[^>]*>\s*([\s\S]*?)\s*<\/span>/i);
    let location = locationMatch ? locationMatch[1].trim() : '';

    // Extract URL
    const urlMatch = card.match(/href="(https:\/\/www\.linkedin\.com\/jobs\/view\/[^"?]+)/i);
    let url = urlMatch ? urlMatch[1] : '';

    // Extract posted date
    const dateMatch = card.match(/datetime="([^"]+)"/i);
    let posted = dateMatch ? dateMatch[1] : 'Recent';

    // Only add if we have title, company, and URL not seen before
    if (title && company && url && !seenUrls.has(url)) {
      seenUrls.add(url);
      allJobs.push({
        title: title,
        company: company,
        location: location,
        url: url,
        posted: posted
      });
    }
  }
}

// Add IDs
const jobs = allJobs.map((job, index) => ({
  id: index + 1,
  ...job
}));

return [{
  json: {
    profile: profile,
    jobs: jobs,
    totalFound: jobs.length,
    searchQuery: searchQuery
  }
}];

const items = $input.all();
const jobsWithJD = [];

for (const item of items) {
  const html = item.json.data || '';

  // Get original job data from Split Out (it's in the pairedItem)
  const splitOutItems = $('Split Out').all();
  const originalJob = splitOutItems[items.indexOf(item)]?.json || {};

  // Fallback: try to get from item itself
  const jobData = {
    id: originalJob.id || item.json.id,
    title: originalJob.title || item.json.title,
    company: originalJob.company || item.json.company,
    location: originalJob.location || item.json.location,
    url: originalJob.url || item.json.url,
    posted: originalJob.posted || item.json.posted
  };

  // Extract job description from HTML
  let description = '';
  const patterns = [
    /class="description__text[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /class="show-more-less-html__markup[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /class="decorated-job-posting__details[^"]*"[^>]*>([\s\S]*?)<\/section>/i
  ];

  for (const pattern of patterns) {
    const match = html.match(pattern);
    if (match && match[1]) {
      description = match[1];
      break;
    }
  }

  // Clean description
  description = description
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#[0-9]+;/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 8000);

  if (!description || description.length < 50) {
    description = `Job Title: ${jobData.title} at ${jobData.company}. Location: ${jobData.location}. (Full description not available)`;
  }

  // Create matchKey
  const matchKey = jobData.title && jobData.company 
    ? `${jobData.title}|||${jobData.company}`.toLowerCase()
    : 'unknown|||unknown';

  jobsWithJD.push({
    id: jobData.id,
    title: jobData.title,
    company: jobData.company,
    location: jobData.location,
    url: jobData.url,
    posted: jobData.posted,
    matchKey: matchKey,
    description: description
  });
}

// Get profile and resume
let profile = {};
let resumeText = '';
try {
  const parseNode = $('Parse Jobs').first().json;
  profile = parseNode.profile || {};
  resumeText = $('Extract from File').first().json.data || '';
} catch(e) {
  profile = { name: 'Unknown' };
}

return [{
  json: {
    profile: profile,
    resumeText: resumeText.slice(0, 4000),
    jobs: jobsWithJD,
    totalJobs: jobsWithJD.length
  }
}];

const input = $input.first().json;

// Get the AI response text from Gemini
let aiResponse = '';
if (input.content?.parts?.[0]?.text) {
  aiResponse = input.content.parts[0].text;
} else if (input.text) {
  aiResponse = input.text;
} else if (input.content) {
  aiResponse = typeof input.content === 'string' ? input.content : JSON.stringify(input.content);
}

// Clean any potential markdown
let cleanedResponse = aiResponse
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

// Parse the JSON array
let rankedJobs = [];
try {
  rankedJobs = JSON.parse(cleanedResponse);
} catch(e) {
  // If direct parse fails, try to extract JSON array
  const jsonMatch = cleanedResponse.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    try {
      rankedJobs = JSON.parse(jsonMatch[0]);
    } catch(e2) {
      return [{
        json: {
          error: 'Failed to parse AI response',
          rawResponse: cleanedResponse.slice(0, 1000),
          parseError: e2.message
        }
      }];
    }
  }
}

// Get profile for context
let profile = {};
try {
  profile = $('Parse AI Results').first().json.profile || {};
} catch(e) {
  profile = { name: 'Job Seeker' };
}

// Filter to only strong matches (optional - already filtered by Gemini)
const strongMatches = rankedJobs.filter(job => job.match_score >= 85);
const goodMatches = rankedJobs.filter(job => job.match_score >= 75);

return [{
  json: {
    profile: profile,
    allMatches: rankedJobs,
    strongMatches: strongMatches,
    goodMatches: goodMatches,
    totalAnalyzed: rankedJobs.length,
    totalStrong: strongMatches.length,
    totalGood: goodMatches.length
  }
}];

const input = $input.first().json;
const profile = input.profile || {};
const jobs = input.allMatches || [];

const today = new Date().toLocaleDateString('en-US', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
});

// Create an array to hold all messages
const messages = [];

// First message: Summary header
let summaryMessage = `🎯 Daily Job Match Report\n`;
summaryMessage += `📅 ${today}\n`;
summaryMessage += `👤 ${profile.name || 'Job Seeker'}\n`;
summaryMessage += `━━━━━━━━━━━━━━━━━━━━\n\n`;

if (jobs.length === 0) {
  summaryMessage += `😕 No strong matches found today.\n\n`;
  summaryMessage += `💡 Try updating your resume or broadening search criteria.`;
  messages.push({ message: summaryMessage });
} else {
  const strongCount = jobs.filter(j => j.match_score >= 95).length;

  summaryMessage += `✨ Found ${jobs.length} excellent opportunities\n`;
  if (strongCount > 0) {
    summaryMessage += `🔥 ${strongCount} exceptional matches (95%+)\n`;
  }
  summaryMessage += `\nSending you the details now...\n`;

  messages.push({ message: summaryMessage });

  // Create one message per job
  jobs.slice(0, 10).forEach((job, index) => {
    // Score emoji
    let scoreEmoji = '🔴';
    if (job.match_score >= 98) scoreEmoji = '🔥';
    else if (job.match_score >= 95) scoreEmoji = '🟢';
    else if (job.match_score >= 90) scoreEmoji = '🟡';
    else if (job.match_score >= 85) scoreEmoji = '🟠';

    let jobMessage = `━━━━━━━━━━━━━━━━━━━━\n`;
    jobMessage += `📋 JOB ${index + 1} of ${jobs.length}\n`;
    jobMessage += `━━━━━━━━━━━━━━━━━━━━\n\n`;

    // Job title and company
    jobMessage += `${job.title}\n`;
    jobMessage += `🏢 ${job.company}\n`;

    if (job.location && job.location !== 'N/A') {
      jobMessage += `📍 ${job.location}\n`;
    }

    jobMessage += `${scoreEmoji} Match Score: ${job.match_score}%\n\n`;

    // Top skills matched
    if (job.skills_matched && job.skills_matched.length > 0) {
      const topSkills = job.skills_matched.slice(0, 6).join(', ');
      jobMessage += `✅ Matched Skills:\n${topSkills}`;
      if (job.skills_matched.length > 6) {
        jobMessage += ` +${job.skills_matched.length - 6} more`;
      }
      jobMessage += `\n\n`;
    }

    // Missing skills
    if (job.skills_missing && job.skills_missing.length > 0 && job.skills_missing.length <= 3) {
      jobMessage += `📚 Consider adding: ${job.skills_missing.join(', ')}\n\n`;
    }

    // Why good fit (truncate if too long)
    if (job.why_good_fit) {
      const fitText = job.why_good_fit.length > 250 
        ? job.why_good_fit.substring(0, 247) + '...' 
        : job.why_good_fit;
      jobMessage += `💡 Why It's a Match:\n${fitText}\n\n`;
    }

    // Application tip (truncate if too long)
    if (job.application_tip) {
      const tipText = job.application_tip.length > 200
        ? job.application_tip.substring(0, 197) + '...'
        : job.application_tip;
      jobMessage += `📝 Application Tip:\n${tipText}\n\n`;
    }

    // Get actual URL from Parse Jobs
    try {
      const parseJobsData = $('Parse Jobs').first().json;
      const originalJob = parseJobsData.jobs.find(j => j.id === job.job_id);
      const jobUrl = originalJob?.url || job.url;

      if (jobUrl && jobUrl !== 'N/A') {
        jobMessage += `🔗 Apply Here:\n${jobUrl}\n`;
      }
    } catch(e) {
      // URL not available
    }

    messages.push({ message: jobMessage });
  });

  // Final message
  const finalMessage = `━━━━━━━━━━━━━━━━━━━━\n\n💪 Good luck with your applications!\n🔄 Next update: Tomorrow at 9 AM`;
  messages.push({ message: finalMessage });
}

// Return all messages as separate items
return messages.map(msg => ({ json: msg }));
